// Settings: the model and the fields to pull out of each document.
const cfg = { openai_model: 'gpt-4o-mini', fields: 'supplier, invoice_number, invoice_date, due_date, subtotal, tax, total, currency' };
const mail = $('New email (IMAP)').item.json;
const text = String($json.text || '').slice(0, 15000);
const request = {
  model: cfg.openai_model,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: `Extract these fields from the document text: ${cfg.fields}. Reply with JSON using exactly those keys. Use null for anything not present. Dates as YYYY-MM-DD, numbers without currency symbols. Add "confidence": "high" | "low".` },
    { role: 'user', content: text },
  ],
};
return { json: { request, from: mail.from, subject: mail.subject, received: mail.date, file: $('New email (IMAP)').item.binary.attachment_0.fileName } };

const meta = $('Build extraction request').item.json;
let f = {};
try { f = JSON.parse($json.choices[0].message.content); } catch (e) { f = { confidence: 'low' }; }
// Send to review when unsure, or when subtotal + tax does not equal total.
const sum = Number(f.subtotal || 0) + Number(f.tax || 0);
const totalsOk = !f.total || !f.subtotal || Math.abs(sum - Number(f.total)) < 0.02;
const review = f.confidence !== 'high' || !totalsOk ? 'CHECK' : 'ok';
const { confidence, ...fields } = f;
return { json: { received: meta.received, from: meta.from, subject: meta.subject, file: meta.file, ...fields, review } };
